def solve(grid):
    if not grid:
        return []

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Collect unique non-zero values and their positions
    unique_vals = set()
    non_zero_cells = []

    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val != 0:
                unique_vals.add(val)
                non_zero_cells.append((r, c, val))

    # If no pattern is present, return the original grid
    if not unique_vals:
        return [row[:] for row in grid]

    # The period is the number of unique values in the pattern
    period = len(unique_vals)

    # Map the remainder of (row+col) to the value
    pattern_map = {}
    for r, c, val in non_zero_cells:
        key = (r + c) % period
        pattern_map[key] = val

    # Generate the output grid by tiling the pattern
    result = [[0 for _ in range(cols)] for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            key = (r + c) % period
            result[r][c] = pattern_map[key]

    return result
